<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Penyewa', href: '/owner/residents' }, { title: 'Detail penyewa', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';

    type Resident = { id: number; full_name: string; whatsapp_number: string; contact_info: string | null; notes: string | null; archived_at: string | null };
    type Tenancy = { id: number; status: string; room_code: string; planned_start_date: string; planned_end_exclusive: string };
    type Booking = { id: number; status: string; planned_start_date: string; planned_end_exclusive: string };
    let { resident, tenancies, bookings }: { resident: Resident; tenancies: Tenancy[]; bookings: Booking[] } = $props();

    const statusLabel: Record<string, string> = { pending: 'Menunggu', confirmed: 'Dikonfirmasi', checked_in: 'Sudah check-in', cancelled: 'Dibatalkan', no_show: 'Tidak hadir', scheduled: 'Terjadwal', active: 'Aktif', completed: 'Selesai', terminated: 'Dihentikan' };
</script>

<AppHead title={resident.full_name} />
<main class="mx-auto w-full max-w-5xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Kontak penyewa</p><h1 class="text-3xl font-semibold tracking-tight">{resident.full_name}</h1><p class="text-sm text-muted-foreground">{resident.archived_at ? 'Diarsipkan' : 'Aktif'}</p></div><div class="flex gap-2"><Link href="/owner/residents" class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Daftar penyewa</Link>{#if !resident.archived_at}<Link href={`/owner/residents/${resident.id}/edit`} class="inline-flex items-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Ubah kontak</Link>{/if}</div></header>
    <section class="grid gap-4 sm:grid-cols-2"><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">WhatsApp</p><a href={`https://wa.me/${resident.whatsapp_number.replace(/\D/g, '')}`} class="mt-2 inline-block font-medium text-primary underline-offset-4 hover:underline">{resident.whatsapp_number}</a></article><article class="rounded-xl border bg-card p-5 shadow-sm"><p class="text-sm text-muted-foreground">Kontak tambahan</p><p class="mt-2 font-medium">{resident.contact_info || '—'}</p></article></section>
    <section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Catatan</h2><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{resident.notes || 'Belum ada catatan.'}</p></section>
    <section class="space-y-3 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Booking</h2><p class="text-sm text-muted-foreground">Riwayat booking penyewa.</p></div>{#if bookings.length === 0}<p class="rounded-md border border-dashed p-4 text-sm text-muted-foreground">Belum ada booking.</p>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[32rem] text-left text-sm"><thead class="border-b text-muted-foreground"><tr><th class="py-3 pr-3 font-medium">Periode</th><th class="py-3 pr-3 font-medium">Status</th><th class="py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each bookings as booking (booking.id)}<tr><td class="py-3 pr-3">{booking.planned_start_date} – {booking.planned_end_exclusive}</td><td class="py-3 pr-3">{statusLabel[booking.status] ?? booking.status}</td><td class="py-3 text-right"><Link href={`/owner/bookings/${booking.id}`} class="text-primary underline-offset-4 hover:underline">Lihat</Link></td></tr>{/each}</tbody></table></div>{/if}</section>
    <section class="space-y-3 rounded-xl border bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Riwayat masa sewa</h2><p class="text-sm text-muted-foreground">Check-out menutup tenancy tanpa menghapus histori.</p></div>{#if tenancies.length === 0}<p class="rounded-md border border-dashed p-4 text-sm text-muted-foreground">Belum ada masa sewa.</p>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[38rem] text-left text-sm"><thead class="border-b text-muted-foreground"><tr><th class="py-3 pr-3 font-medium">Kamar</th><th class="py-3 pr-3 font-medium">Periode rencana</th><th class="py-3 pr-3 font-medium">Status</th><th class="py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each tenancies as tenancy (tenancy.id)}<tr><td class="py-3 pr-3">{tenancy.room_code}</td><td class="py-3 pr-3">{tenancy.planned_start_date} – {tenancy.planned_end_exclusive}</td><td class="py-3 pr-3">{statusLabel[tenancy.status] ?? tenancy.status}</td><td class="py-3 text-right"><Link href={`/owner/tenancies/${tenancy.id}`} class="text-primary underline-offset-4 hover:underline">Lihat</Link></td></tr>{/each}</tbody></table></div>{/if}</section>
    {#if !resident.archived_at}<section class="space-y-4 rounded-xl border border-amber-300/60 bg-card p-5 shadow-sm"><div><h2 class="font-semibold">Arsipkan penyewa</h2><p class="mt-1 text-sm text-muted-foreground">Data riwayat tetap tersimpan. Arsip hanya dapat dilakukan bila tidak ada alur aktif yang memerlukan kontak ini.</p></div><Form action={`/owner/residents/${resident.id}/archive`} method="post" class="space-y-3">{#snippet children({ errors, processing })}<label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya memahami kontak ini akan diarsipkan.</span></label><InputError message={errors.archive} /><div class="flex justify-end"><Button type="submit" variant="destructive" disabled={processing}>{processing ? 'Mengarsipkan…' : 'Arsipkan penyewa'}</Button></div>{/snippet}</Form></section>{/if}
</main>
